const SHIPTO_HISTORY_KEY="wf_shipto_history";
const getShiptoHistory=()=>{try{return JSON.parse(localStorage.getItem(SHIPTO_HISTORY_KEY)||"{}");}catch(e){return{};}};
const getLastShipto=(custCode)=>{if(!custCode)return null;const h=getShiptoHistory();return h[custCode]||null;};
const saveLastShipto=(custCode,shipTo,destZip,fob)=>{
  if(!custCode)return;
  // Skip empty/default-only saves so the first auto-loaded customer doesn't clobber a real history entry with blanks
  if(!shipTo&&!destZip)return;
  try{
    const h=getShiptoHistory();
    h[custCode]={shipTo:shipTo||"",destZip:destZip||"",fob:fob||"Origin",savedAt:new Date().toISOString()};
    localStorage.setItem(SHIPTO_HISTORY_KEY,JSON.stringify(h));
  }catch(e){}
};
