    const zip=destZip||(shipToZip2?shipToZip2[1]:"");
    if(!zip||zip.length<5){setToast("\u26A0 Enter a ship-to ZIP first");return;}
    if(!isMultiPart||!allItemsCosts||allItemsCosts.length<2){setToast("Comparison requires a multi-part quote with 2+ items");return;}

