        if(!slotMap[c.slot]) slotMap[c.slot]=[];
        slotMap[c.slot].push({idx:item.idx,desc:item.desc,weight:sh.totalWeight,qty:c.totalQty,skids:sh.skidCount,trailerFt:sh.trailerFeet});
