                          {activeSlots.map(st=>{const fc=aic&&aic.costs&&aic.costs.find(c=>c.slot===st.slot);let sp=0;if(st.itemSells&&st.itemSells[i]){sp=st.itemSells[i].qty>0?st.itemSells[i].sell/st.itemSells[i].qty:0;}else if(fc&&fc.totalQty>0){sp=(fc.itemSell||0)/fc.totalQty;}return <td key={st.slot} style={{padding:"4px 8px",textAlign:"right"}}>{sp>0?fm(sp)+"/pc":"\u2014"}</td>;})}
