                        {hasFrt&&<tr><td style={{padding:"4px 8px",color:"#6b7280",fontStyle:"italic"}}>Freight</td>{activeSlots.map(st=><td key={st.slot} style={{padding:"4px 8px",textAlign:"right",color:"#6b7280"}}>{slotFrt[st.slot]>0?fm(slotFrt[st.slot]):"\u2014"}</td>)}</tr>}
                        {totalPrepress>0&&<tr><td style={{padding:"4px 8px",color:"#6b7280",fontStyle:"italic"}}>Prepress</td>{activeSlots.map(st=><td key={st.slot} style={{padding:"4px 8px",textAlign:"right",color:"#6b7280"}}>{fm(totalPrepress)}</td>)}</tr>}
                        {totalMisc>0&&<tr><td style={{padding:"4px 8px",color:"#6b7280",fontStyle:"italic"}}>Misc</td>{activeSlots.map(st=><td key={st.slot} style={{padding:"4px 8px",textAlign:"right",color:"#6b7280"}}>{fm(totalMisc)}</td>)}</tr>}
